import{_ as a,a0 as l,w as d,s as o,ao as r,I as n,x as t,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 命令列操作 PDF | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 命令列操作 PDF | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 命令列操作 PDF | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 命令列操作 PDF | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190808 How to manipulate PDFs on Linux","title":"如何在 Linux 命令列操作 PDF","tag":"201908","desc":""},"relativePath":"201908/20190808 How to manipulate PDFs on Linux.md","filePath":"[post].md"}'),u={name:"201908/20190808 How to manipulate PDFs on Linux.md"};function g(f,s,h,k,b,c){const p=l("Link");return d(),o("div",null,[s[19]||(s[19]=r(`<h1 id="如何在-linux-命令列操作-pdf" tabindex="-1">如何在 Linux 命令列操作 PDF <a class="header-anchor" href="#如何在-linux-命令列操作-pdf" aria-label="Permalink to “如何在 Linux 命令列操作 PDF”">​</a></h1><blockquote><p>pdftk 命令提供了許多處理 PDF 的命令列操作，包括合併頁面、加密文件、添加水印、壓縮文件，甚至還有修復 PDF。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201908/15/110119x6sjnjs6s22srnje.jpg" alt=""></p><p>雖然 PDF 通常被認為是相當穩定的文件，但在 Linux 和其他系統上你可以做很多處理。包括合併、拆分、旋轉、拆分成單頁、加密和解密、添加水印、壓縮和解壓縮，甚至還有修復。 <code>pdftk</code> 命令能執行所有甚至更多操作。</p><p>“pdftk” 代表 “PDF 工具包”（PDF tool kit），這個命令非常易於使用，並且可以很好地操作 PDF。例如，要將獨立的文件合併成一個文件，你可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pdftk pg1.pdf pg2.pdf pg3.pdf pg4.pdf pg5.pdf cat output OneDoc.pdf</span></span></code></pre></div><p><code>OneDoc.pdf</code> 將包含上面顯示的所有五個文檔，命令將在幾秒鐘內運行完畢。請注意，<code>cat</code> 選項表示將文件連接在一起，<code>output</code> 選項指定新文件的名稱。</p><p>你還可以從 PDF 中提取選定頁面來創建單獨的 PDF 文件。例如，如果要創建僅包含上面創建的文檔的第 1、2、3 和 5 頁的新 PDF，那麼可以執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pdftk OneDoc.pdf cat 1-3 5 output 4pgs.pdf</span></span></code></pre></div><p>另外，如果你想要第 1、3、4 和 5 頁（總計 5 頁），我們可以使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pdftk OneDoc.pdf cat 1 3-end output 4pgs.pdf</span></span></code></pre></div><p>你可以選擇單獨頁面或者頁面範圍，如上例所示。</p><p>下一個命令將從一個包含奇數頁（1、3 等）的文件和一個包含偶數頁（2、4 等）的文件創建一個整合文檔：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pdftk A=odd.pdf B=even.pdf shuffle A B output collated.pdf</span></span></code></pre></div><p>請注意，<code>shuffle</code> 選項使得能夠完成整合，並指示文檔的使用順序。另請注意：雖然上面建議用的是奇數/偶數頁，但你不限於僅使用兩個文件。</p><p>如果要創建只能由知道密碼的收件人打開的加密 PDF，可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pdftk prep.pdf output report.pdf user_pw AsK4n0thingGeTn0thing</span></span></code></pre></div><p>選項提供 40（<code>encrypt_40bit</code>）和 128（<code>encrypt_128bit</code>）位加密。默認情況下使用 128 位加密。</p><p>你還可以使用 <code>burst</code> 選項將 PDF 文件分成單個頁面：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pdftk allpgs.pdf burst</span></span>
<span class="line"><span>$ ls -ltr *.pdf | tail -5</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   22933 Aug  8 08:18 pg_0001.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   23773 Aug  8 08:18 pg_0002.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   23260 Aug  8 08:18 pg_0003.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   23435 Aug  8 08:18 pg_0004.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 shs shs   23136 Aug  8 08:18 pg_0005.pdf</span></span></code></pre></div>`,20)),n("p",null,[s[1]||(s[1]=n("code",null,"pdftk",-1)),s[2]||(s[2]=t(" 命令使得合併、拆分、重建、加密 PDF 文件非常容易。要了解更多選項，請查看 ",-1)),i(p,{href:"https://www.pdflabs.com/docs/pdftk-cli-examples/"},{default:e(()=>[...s[0]||(s[0]=[t("PDF 實驗室",-1)])]),_:1}),s[3]||(s[3]=t("中的示例頁面。",-1))]),s[20]||(s[20]=n("hr",null,null,-1)),n("p",null,[s[5]||(s[5]=t("via: ",-1)),i(p,{href:"https://www.networkworld.com/article/3430781/how-to-manipulate-pdfs-on-linux.html"},{default:e(()=>[...s[4]||(s[4]=[t("https://www.networkworld.com/article/3430781/how-to-manipulate-pdfs-on-linux.html",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=t("作者：",-1)),i(p,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:e(()=>[...s[6]||(s[6]=[t("Sandra Henry-Stocker",-1)])]),_:1}),s[11]||(s[11]=t(" 選題：",-1)),i(p,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[7]||(s[7]=[t("lujun9972",-1)])]),_:1}),s[12]||(s[12]=t(" 譯者：",-1)),i(p,{href:"https://github.com/geekpi"},{default:e(()=>[...s[8]||(s[8]=[t("geekpi",-1)])]),_:1}),s[13]||(s[13]=t(" 校對：",-1)),i(p,{href:"https://github.com/wxy"},{default:e(()=>[...s[9]||(s[9]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=t("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[14]||(s[14]=[t("LCTT",-1)])]),_:1}),s[17]||(s[17]=t(" 原創編譯，",-1)),i(p,{href:"https://linux.cn/"},{default:e(()=>[...s[15]||(s[15]=[t("Linux中國",-1)])]),_:1}),s[18]||(s[18]=t(" 榮譽推出",-1))])])}const D=a(u,[["render",g]]);export{x as __pageData,D as default};
